	@Test
	void modernOwnerReusesExactAndGeneralizedActualSurfacesWithoutRewritingTheirPayload(@TempDir Path directory)
			throws Exception {
		Filter recorded;
			FilterDescriptorSurfaces descriptor;
		try (Fixture first = Fixture.modern(directory)) {
			first.load();
			try (Compiled compiled = first.compile(PATTERN)) {
				recorded = first.teach(compiled, 11L, 8L);
				descriptor = descriptor(recorded);
				first.filters().persistIfDirty();
			}
			first.store.getBackingStore().getSketchBasedJoinEstimator().persistIfDirty();
		}
		Path file = directory.resolve("join-estimator.rjes.filters");
		assertTrue(Files.isRegularFile(file));
		byte[] bytes = Files.readAllBytes(file);
		try (Fixture second = Fixture.modern(directory)) {
			assertArrayEquals(bytes, Files.readAllBytes(file));
			var exact = second.filters().estimateLearnedSurface(recorded);
			assertEstimate(exact, 8.0d / 11.0d, 11L, false);
			assertEquals(descriptor.exact().toString(), exact.evidenceKey());
			try (Compiled probe = second.compile(OTHER_PATTERN)) {
				var actualProbe = descriptor(probe.filter());
				assertNotEquals(descriptor.exact(), actualProbe.exact());
				assertEquals(descriptor.generalized(), actualProbe.generalized());
				var generalized = second.filters().estimateLearnedSurface(probe.filter());
				assertEstimate(generalized, 8.0d / 11.0d, 11L, true);
				assertEquals(descriptor.generalized().toString(), generalized.evidenceKey());
			}
			assertArrayEquals(bytes, Files.readAllBytes(file), "read-only exact/generalized lookup does not publish a replacement");
		}
		assertArrayEquals(bytes, Files.readAllBytes(file), "clean reopen/close leaves the prior recognized payload intact");
	}

