	private static String query(String predicate, String pattern) {
		return "SELECT ?s WHERE { ?s <" + predicate + "> ?o FILTER(REGEX(STR(?o), \"" + pattern + "\")) }";
	}

	private static FilterDescriptorSurfaces descriptor(Filter filter) {
		var contract = filter.getRuntimeFeedbackContract();
		assertNotNull(contract);
		assertTrue(contract.admits(RuntimeFeedbackContract.ADMIT_FILTER));
		Object descriptor = contract.descriptor();
		FilterSurfaceKey exact;
		FilterSurfaceKey generalized;
		if (descriptor instanceof LmdbRuntimeFeedbackDescriptor runtime) {
			exact = runtime.exactFilterSurfaceKey();
			generalized = runtime.generalizedFilterSurfaceKey();
		} else if (descriptor instanceof LmdbFilterOutcomeFeedbackDescriptor outcome) {
			exact = outcome.exact();
			generalized = outcome.generalized();
		} else {
			throw new AssertionError("unexpected actual FILTER contract descriptor: " + descriptor);
		}
		assertNotNull(exact);
		assertNotNull(generalized);
		return new FilterDescriptorSurfaces(descriptor.getClass(), exact, generalized);
	}

	private record FilterDescriptorSurfaces(Class<?> descriptorType, FilterSurfaceKey exact,
			FilterSurfaceKey generalized) {
	}

	private static void assertEstimate(LmdbFilterSelectivityStats.LearnedSurfaceEstimate estimate,
			double ratio, long inputs, boolean generalized) {
		assertNotNull(estimate);
		assertEquals(ratio, estimate.passRatio(), 1e-12);
		assertEquals(inputs, estimate.evidenceCount());
		assertEquals(generalized, estimate.generalized());
	}

	private record Compiled(SailDataset dataset, LmdbEvaluationStatistics statistics, Filter filter,
			QueryEvaluationStep step) implements AutoCloseable {
		List<String> subjects() {
			try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
				return QueryResults.asList(rows).stream().map(row -> row.getValue("s").stringValue()).sorted().toList();
			}
		}
		@Override public void close() { dataset.close(); }
	}

